/* ══════════════════════════════════════════════════════════════════
   MOTION PRIMITIVES
   Native IntersectionObserver — no Framer Motion.
   Only transform + opacity animated → guaranteed 60fps.
   prefers-reduced-motion respected throughout.
══════════════════════════════════════════════════════════════════ */
function prefersReducedMotion() {
  if (typeof window === "undefined" || !window.matchMedia) return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

function useInView(opts = { threshold: 0.13, rootMargin: "0px 0px -6% 0px" }) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (prefersReducedMotion()) { setInView(true); return; }
    const io = new IntersectionObserver((entries) => {
      entries.forEach((e) => { if (e.isIntersecting) { setInView(true); io.unobserve(e.target); } });
    }, opts);
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return [ref, inView];
}

function FadeUp({ children, delay = 0, y = 20, scaleFrom = 1, className = "", style = {}, as: Tag = "div" }) {
  const [ref, inView] = useInView();
  const skip = prefersReducedMotion();
  const hidden = scaleFrom !== 1
    ? `translateY(${y}px) scale(${scaleFrom})`
    : `translateY(${y}px)`;
  return (
    <Tag ref={ref} className={className} style={{
      opacity: inView ? 1 : 0,
      transform: inView ? "translateY(0) scale(1)" : hidden,
      transition: skip ? "none"
        : `opacity 600ms cubic-bezier(0.16,1,0.3,1) ${delay}ms,
           transform 600ms cubic-bezier(0.16,1,0.3,1) ${delay}ms`,
      willChange: "opacity, transform", ...style,
    }}>
      {children}
    </Tag>
  );
}

/* ── Count-up: animates a number 0→end when scrolled into view.
   Uses requestAnimationFrame; respects reduced motion (shows end value). */
function CountUp({ end, duration = 1400, className, style }) {
  const [ref, inView] = useInView();
  const [val, setVal] = useState(0);
  const startedRef = useRef(false);
  useEffect(() => {
    if (!inView || startedRef.current) return;
    startedRef.current = true;
    if (prefersReducedMotion()) { setVal(end); return; }
    let raf;
    const t0 = performance.now();
    const tick = (now) => {
      const p = Math.min((now - t0) / duration, 1);
      // easeOutCubic
      const eased = 1 - Math.pow(1 - p, 3);
      setVal(Math.round(eased * end));
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [inView, end, duration]);
  return <span ref={ref} className={className} style={style}>{val}</span>;
}

/* ── Line-by-line headline reveal with clip-mask.
   Each line rises from behind an invisible edge, staggered. */
function RevealHeadline({ text, lang, style, baseDelay = 0 }) {
  const lines = text.replace(/\\n/g, "\n").split("\n");
  return (
    <h1 style={{ ...style }}>
      {lines.map((line, i) => (
        <RevealLine key={i} delay={baseDelay + i * 130}>{line}</RevealLine>
      ))}
    </h1>
  );
}
function RevealLine({ children, delay = 0 }) {
  const [ref, inView] = useInView({ threshold: 0.1 });
  const skip = prefersReducedMotion();
  return (
    <span ref={ref} style={{ display: "block", overflow: "hidden", paddingBottom: "0.06em" }}>
      <span style={{
        display: "block",
        transform: inView ? "translateY(0)" : "translateY(105%)",
        opacity: inView ? 1 : 0,
        transition: skip ? "none"
          : `transform 720ms cubic-bezier(0.16,1,0.3,1) ${delay}ms,
             opacity 720ms cubic-bezier(0.16,1,0.3,1) ${delay}ms`,
        willChange: "transform, opacity",
      }}>
        {children}
      </span>
    </span>
  );
}

/* ══════════════════════════════════════════════════════════════════
   LOGO COMPONENT
   Uses the official transparent PNG (WebP for web).
   The serif letterforms (#B0B2B2) and orange accent (#F8A740)
   are baked into the asset — pixel-faithful, not CSS-rendered.
   Aspect ratio of cropped asset: 277:140 ≈ 1.979:1
══════════════════════════════════════════════════════════════════ */
function Logo({ height = 38 }) {
  const w = Math.round((277 / 140) * height);
  return (
    <img src={LOGO_SRC} width={w} height={height} alt="MPL Design & Build"
      style={{ display: "block", height, width: "auto" }} decoding="async" />
  );
}

/* ══════════════════════════════════════════════════════════════════
   SHARED ATOM COMPONENTS
══════════════════════════════════════════════════════════════════ */

/* Typography helpers — RTL-aware */
function fontDisplay(lang) {
  return lang === "ar"
    ? { fontFamily: "'IBM Plex Sans Arabic', system-ui, sans-serif", fontWeight: 600, letterSpacing: 0, lineHeight: 1.22 }
    : { fontFamily: "'Space Grotesk', system-ui, sans-serif",        fontWeight: 500, letterSpacing: "-0.02em", lineHeight: 1.04 };
}
function fontBody(lang) {
  return lang === "ar"
    ? { fontFamily: "'IBM Plex Sans Arabic', system-ui, sans-serif", fontWeight: 500, lineHeight: 1.9 }
    : { fontFamily: "'Inter', system-ui, sans-serif",                 fontWeight: 400, lineHeight: 1.74 };
}

/* Orange eyebrow rule — mirrors the PDF's divider language exactly */
function Eyebrow({ index, label, lang, inverse = false }) {
  const isAr = lang === "ar";
  return (
    <div className="flex items-center gap-3">
      {index && (
        <span style={{
          fontFamily: isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Space Grotesk', sans-serif",
          fontSize: "0.7rem", fontWeight: 600, letterSpacing: isAr ? 0 : "0.18em",
          color: C.orange,
        }}>{index}</span>
      )}
      <span aria-hidden style={{ width: 28, height: 1, background: C.orange }} />
      <span style={{
        fontFamily: isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Inter', sans-serif",
        fontSize: "0.7rem", fontWeight: 500,
        letterSpacing: isAr ? 0 : "0.22em",
        textTransform: isAr ? "none" : "uppercase",
        color: inverse ? C.inkInverseDim : C.inkTertiary,
      }}>{label}</span>
    </div>
  );
}

function SectionHeading({ children, lang, style = {}, inverse = false }) {
  const fd = fontDisplay(lang);
  return (
    <h2 style={{
      ...fd,
      fontSize: "clamp(2rem, 4.6vw, 3.4rem)",
      color: inverse ? C.inkInverse : C.inkPrimary,
      ...style,
    }}>{children}</h2>
  );
}

function BodyText({ children, lang, style = {}, inverse = false }) {
  const fb = fontBody(lang);
  return (
    <p style={{
      ...fb, fontSize: "1.02rem",
      color: inverse ? C.inkInverseDim : C.inkSecondary,
      ...style,
    }}>{children}</p>
  );
}

function SpecTag({ label, lang }) {
  const isAr = lang === "ar";
  return (
    <span style={{
      fontFamily: isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Inter', sans-serif",
      fontSize: "0.72rem", letterSpacing: isAr ? 0 : "0.05em",
      color: C.inkTertiary, border: `1px solid ${C.hairlineStrong}`,
      borderRadius: 2, padding: "5px 11px", whiteSpace: "nowrap",
    }}>{label}</span>
  );
}

/* Compliance badge — success green ONLY, never used for other elements */
function ComplianceBadge({ code, nameStr, lang }) {
  const isAr = lang === "ar";
  return (
    <div className="mpl-cbadge flex items-center gap-3" style={{
      background: C.white, border: "1px solid rgba(26,122,74,0.28)",
      borderRadius: 2, padding: "12px 16px",
    }}>
      <ShieldCheck size={18} style={{ color: C.success, flexShrink: 0 }} aria-hidden />
      <div>
        <div style={{
          fontFamily: isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Space Grotesk', sans-serif",
          fontSize: "0.95rem", fontWeight: 600, letterSpacing: isAr ? 0 : "0.04em",
          color: C.inkPrimary,
        }}>{code}</div>
        <div style={{
          fontFamily: isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Inter', sans-serif",
          fontSize: "0.68rem", color: C.inkTertiary, lineHeight: 1.3,
          letterSpacing: isAr ? 0 : "0.03em",
        }}>{nameStr}</div>
      </div>
    </div>
  );
}

/* Gap placeholder — styled stakeholder data request */
function GapBlock({ fields, notice, lang }) {
  const isAr = lang === "ar";
  return (
    <div style={{
      border: `2px dashed rgba(248,167,64,0.45)`,
      borderRadius: 4, padding: "32px 28px",
      background: "rgba(248,167,64,0.04)",
    }}>
      <div style={{
        fontFamily: isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Inter', sans-serif",
        fontSize: "0.7rem", fontWeight: 600,
        letterSpacing: isAr ? 0 : "0.16em",
        textTransform: isAr ? "none" : "uppercase",
        color: C.orange, marginBottom: 20,
      }}>{notice}</div>
      {fields.map((f, i) => (
        <div key={i} style={{
          fontFamily: isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Inter', sans-serif",
          fontSize: "0.88rem", fontWeight: 400,
          color: C.inkTertiary, padding: "10px 0",
          borderBottom: i < fields.length - 1 ? `1px dashed ${C.hairlineStrong}` : "none",
        }}>{f}</div>
      ))}
    </div>
  );
}

/* ══════════════════════════════════════════════════════════════════
   GLOBAL NAVIGATION
   RTL-aware: CSS logical properties, language toggle, logo as PNG asset.
   No sticky — Authoritative Friction principle.
══════════════════════════════════════════════════════════════════ */
function Nav({ lang, setLang, activeSection, onNavTo, navRef }) {
  const t = T[lang].nav;
  const isAr = lang === "ar";
  const ff = isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Inter', sans-serif";
  const [menuOpen, setMenuOpen] = useState(false);

  /* activeSection drives nav appearance.
     hero → fully transparent + white text
     other sections → frosted glass (semi-transparent white + blur) + dark text */
  const onHero    = activeSection === "home";
  const navBg     = onHero ? "transparent"                  : "rgba(255,255,255,0.72)";
  const navBlur   = onHero ? "none"                         : "blur(16px)";
  const navBorder = onHero ? "transparent"                  : "rgba(42,40,38,0.08)";
  const linkOn    = onHero ? C.inkInverse                   : C.inkPrimary;
  const linkOff   = onHero ? "rgba(240,237,230,0.62)"      : C.inkTertiary;

  const pages = [
    { id: "home",      label: t.home },
    { id: "expertise", label: t.expertise },
    { id: "work",      label: t.work },
    { id: "company",   label: t.company },
  ];

  const go = (id) => { setMenuOpen(false); onNavTo(id); };

  return (
    <header ref={navRef} style={{
      background: navBg,
      borderBottom: `1px solid ${navBorder}`,
      backdropFilter: navBlur,
      WebkitBackdropFilter: navBlur,
      position: "fixed", top: 0, left: 0, right: 0, width: "100%", zIndex: 100,
      transition: "background 400ms ease, border-color 400ms ease, backdrop-filter 400ms ease",
    }}>
      <div style={{ maxWidth: 1280, marginInline: "auto", paddingInline: "clamp(18px, 5vw, 72px)" }}
        className="flex items-center justify-between">

        {/* Logo → scroll to top */}
        <button onClick={() => go("home")} style={{ background: "none", border: "none", cursor: "pointer", paddingBlock: 16, lineHeight: 0 }}
          aria-label="MPL — home">
          <Logo height={68} />
        </button>

        <div className="flex items-center" style={{ gap: "clamp(12px, 2vw, 28px)" }}>
          {/* Desktop links */}
          <nav className="mpl-nav-links" aria-label="Main navigation">
            {pages.map((p) => {
              const on = activeSection === p.id;
              return (
                <button key={p.id} onClick={() => go(p.id)}
                  style={{
                    fontFamily: ff, fontSize: "0.82rem", fontWeight: 500,
                    letterSpacing: isAr ? 0 : "0.04em",
                    color: on ? linkOn : linkOff,
                    background: "none", border: "none", cursor: "pointer",
                    borderBottom: on ? `2px solid ${C.orange}` : "2px solid transparent",
                    paddingBottom: 3,
                    transition: "color 300ms ease, border-color 300ms ease",
                  }}>
                  {p.label}
                </button>
              );
            })}
          </nav>

          {/* Language toggle — adapts to glass/solid */}
          <button
            onClick={() => setLang()}
            aria-label={lang === "ar" ? "Switch to English" : "التبديل إلى العربية"}
            className="mpl-lang-toggle"
            style={{
              fontFamily: lang === "ar" ? "'Space Grotesk', sans-serif" : "'IBM Plex Sans Arabic', sans-serif",
              fontSize: "0.76rem", fontWeight: 600,
              letterSpacing: lang === "ar" ? "0.08em" : 0,
              color: onHero ? C.inkInverse : C.inkPrimary,
              background: onHero ? "rgba(240,237,230,0.15)" : "rgba(42,40,38,0.04)",
              border: onHero ? "1px solid rgba(240,237,230,0.38)" : `1px solid ${C.hairline}`,
              borderRadius: 2, padding: "7px 13px", cursor: "pointer",
              transition: "background 300ms ease, border-color 300ms ease",
              flexShrink: 0,
            }}>
            {t.langToggle}
          </button>

          {/* Mobile hamburger */}
          <button className="mpl-burger" onClick={() => setMenuOpen((v) => !v)}
            aria-label={menuOpen ? "Close menu" : "Open menu"} aria-expanded={menuOpen}
            style={{
              background: "none", border: "none", cursor: "pointer",
              color: onHero ? C.inkInverse : C.inkPrimary,
              padding: 6, lineHeight: 0, flexShrink: 0,
              transition: "color 300ms ease",
            }}>
            {menuOpen ? <X size={24} strokeWidth={1.7} /> : <Menu size={24} strokeWidth={1.7} />}
          </button>
        </div>
      </div>

      {/* Mobile dropdown menu — always white */}
      <div className="mpl-mobile-menu" style={{
        maxHeight: menuOpen ? 320 : 0,
        opacity: menuOpen ? 1 : 0,
        overflow: "hidden",
        borderTop: menuOpen ? `1px solid ${C.hairline}` : "1px solid transparent",
        transition: prefersReducedMotion() ? "none" : "max-height 320ms cubic-bezier(0.16,1,0.3,1), opacity 240ms ease",
        background: C.white,
      }}>
        <nav aria-label="Mobile navigation" style={{ padding: "8px clamp(18px,5vw,72px) 16px" }}>
          {pages.map((p) => {
            const on = activeSection === p.id;
            return (
              <button key={p.id} onClick={() => go(p.id)} style={{
                display: "block", width: "100%", textAlign: isAr ? "right" : "left",
                fontFamily: ff, fontSize: "1rem", fontWeight: 500,
                color: on ? C.orange : C.inkPrimary,
                background: "none", border: "none", cursor: "pointer",
                padding: "14px 0", borderBottom: `1px solid ${C.hairline}`,
              }}>
                {p.label}
              </button>
            );
          })}
          {/* Lang toggle inside mobile menu */}
          <button onClick={() => { setMenuOpen(false); setLang(); }}
            style={{
              display: "block", width: "100%", textAlign: isAr ? "right" : "left",
              fontFamily: lang === "ar" ? "'Space Grotesk', sans-serif" : "'IBM Plex Sans Arabic', sans-serif",
              fontSize: "0.9rem", fontWeight: 600,
              letterSpacing: lang === "ar" ? "0.08em" : 0,
              color: C.inkTertiary, background: "none", border: "none", cursor: "pointer",
              padding: "14px 0", marginTop: 4,
            }}>
            {t.langToggle}
          </button>
        </nav>
      </div>
    </header>
  );
}

