/* ── Hero */
function HeroSection({ lang, onNavigate, onInquire }) {
  const t = T[lang].home.hero;
  const isAr = lang === "ar";
  const ff = isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Space Grotesk', sans-serif";

  /* Responsive image src — swapped on resize */
  const [heroSrc, setHeroSrc] = useState(HERO_IMG.desktop);
  useEffect(() => {
    const pick = () => {
      const w = window.innerWidth;
      setHeroSrc(w <= 640 ? HERO_IMG.mobile : w <= 1024 ? HERO_IMG.tablet : HERO_IMG.desktop);
    };
    pick();
    window.addEventListener("resize", pick, { passive: true });
    return () => window.removeEventListener("resize", pick);
  }, []);

  return (
    <section
      className="mpl-hero-section"
      style={{
        position: "relative",
        backgroundColor: C.dark,          /* fallback color only — no shorthand reset */
        backgroundImage: `url(${heroSrc})`,
        minHeight: "100svh",
        display: "flex", flexDirection: "column",
      }}
    >
      {/* Cinematic overlay */}
      <div className="mpl-hero-overlay" aria-hidden />

      {/* Hero content — vertically centred within the cinematic frame */}
      <div style={{
        maxWidth: 1280, marginInline: "auto",
        paddingInline: "clamp(22px, 5vw, 80px)",
        paddingTop: "clamp(100px, 18vw, 220px)",
        paddingBottom: "clamp(72px, 10vw, 140px)",
        position: "relative", zIndex: 1,
        width: "100%", flex: 1,
        display: "flex", flexDirection: "column", justifyContent: "flex-end",
      }}>

        {/* Eyebrow — premium horizontal rule + label */}
        <FadeUp>
          <div style={{
            display: "inline-flex", alignItems: "center",
            gap: 14, marginBottom: "clamp(24px, 3vw, 40px)",
          }}>
            <span aria-hidden style={{
              display: "inline-block", width: 32, height: 1.5,
              background: C.orange, flexShrink: 0,
            }} />
            <span style={{
              fontFamily: isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Inter', sans-serif",
              fontSize: isAr ? "0.85rem" : "0.7rem",
              fontWeight: isAr ? 500 : 500,
              letterSpacing: isAr ? "0.02em" : "0.18em",
              textTransform: isAr ? "none" : "uppercase",
              color: "rgba(248,167,64,0.90)",
              lineHeight: 1,
            }}>
              {t.eyebrow}
            </span>
          </div>
        </FadeUp>

        {/* Headline — refined scale, elegant line breaks */}
        <RevealHeadline
          text={t.headline}
          lang={lang}
          baseDelay={80}
          style={{
            ...fontDisplay(lang),
            fontSize: "clamp(2.2rem, 5.2vw, 5rem)",
            lineHeight: isAr ? 1.20 : 1.05,
            color: C.inkInverse,
            maxWidth: isAr ? "16ch" : "18ch",
            letterSpacing: isAr ? "-0.01em" : "-0.02em",
            textShadow: "0 2px 24px rgba(10,8,6,0.55), 0 1px 4px rgba(10,8,6,0.35)",
          }}
        />

        {/* Sub-paragraph — full width below headline, reads before CTAs */}
        <FadeUp delay={200}>
          <p style={{
            fontFamily: isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Inter', sans-serif",
            fontSize: isAr ? "1rem" : "1.02rem",
            fontWeight: isAr ? 400 : 300,
            lineHeight: isAr ? 1.85 : 1.65,
            color: "rgba(240,237,230,0.90)",
            textShadow: "0 1px 12px rgba(10,8,6,0.50)",
            maxWidth: "52ch",
            marginTop: "clamp(24px, 3.2vw, 44px)",
            letterSpacing: isAr ? "0.01em" : 0,
          }}>{t.sub}</p>
        </FadeUp>

        {/* CTA row — clear hierarchy, enterprise-grade sizing */}
        <FadeUp delay={300}>
          <div style={{
            display: "flex", flexWrap: "wrap",
            gap: "clamp(10px, 1.5vw, 16px)",
            marginTop: "clamp(32px, 4vw, 52px)",
            alignItems: "center",
          }}>
            {/* Primary — leads to Expertise */}
            <button
              onClick={() => onNavigate("expertise")}
              className="mpl-solid-btn"
              style={{
                fontFamily: ff,
                fontSize: isAr ? "0.95rem" : "0.85rem",
                fontWeight: 600,
                letterSpacing: isAr ? "0.01em" : "0.04em",
                color: C.dark, background: C.orange,
                border: `1.5px solid ${C.orange}`,
                borderRadius: 3,
                padding: isAr ? "15px 28px" : "15px 26px",
                cursor: "pointer", whiteSpace: "nowrap",
                display: "inline-flex", alignItems: "center",
                gap: 10, transition: "background-color 240ms",
                minHeight: 50,
              }}>
              {t.cta}
              {isAr
                ? <ArrowLeft className="mpl-arrow" size={16} strokeWidth={2.2} aria-hidden />
                : <ArrowRight className="mpl-arrow" size={16} strokeWidth={2.2} aria-hidden />}
            </button>

            {/* Secondary — leads to Work/Projects */}
            <button
              onClick={() => onNavigate("work")}
              className="mpl-hero-cta"
              style={{
                fontFamily: ff,
                fontSize: isAr ? "0.95rem" : "0.85rem",
                fontWeight: isAr ? 500 : 500,
                letterSpacing: isAr ? "0.01em" : "0.04em",
                color: "rgba(240,237,230,0.88)",
                background: "rgba(240,237,230,0.08)",
                border: "1.5px solid rgba(240,237,230,0.28)",
                borderRadius: 3,
                padding: isAr ? "15px 28px" : "15px 26px",
                cursor: "pointer", whiteSpace: "nowrap",
                display: "inline-flex", alignItems: "center",
                gap: 10,
                transition: "border-color 240ms, background-color 240ms, color 240ms",
                backdropFilter: "blur(6px)",
                WebkitBackdropFilter: "blur(6px)",
                minHeight: 50,
              }}>
              {t.secondaryCta}
              <ArrowUpRight size={15} strokeWidth={2} style={{ color: C.orange }} aria-hidden />
            </button>
          </div>
        </FadeUp>
      </div>
    </section>
  );
}

