/* ══════════════════════════════════════════════════════════════════
   CONTACT SECTION — dark bookend (~#2A2826)
   Real-world integration: phone, email, Google Maps, LinkedIn.
   Mirrors the visual language of the PDF's closing contact page.
   Dual-path conversion: Authoritative Friction principle.
   Contrast check: #F8A740 on #2A2826 = 6.77:1 (WCAG AA ✓)
══════════════════════════════════════════════════════════════════ */
function ContactSection({ lang, onInquire }) {
  const t = T[lang].contact;
  const isAr = lang === "ar";
  const ff = isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Inter', sans-serif";
  const wrap = { maxWidth: 1180, marginInline: "auto", paddingInline: "clamp(20px, 5vw, 72px)" };

  const MAP_URL = "https://maps.app.goo.gl/4cwSQ68KjnXPnAXR7?g_st=ic";
  const LI_URL  = "https://www.linkedin.com/company/mpl-modern-project-leaders/";
  const PDF_URL = "./MPL-Company-Profile.pdf";

  // A single contact detail block — icon, label, value (premium, evenly weighted)
  const detail = (Icon, label, value, href, ltr) => (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
      <div style={{
        width: 44, height: 44, borderRadius: 3,
        border: `1px solid ${C.hairlineInverse}`,
        display: "flex", alignItems: "center", justifyContent: "center",
        background: "rgba(248,167,64,0.06)",
      }}>
        <Icon size={19} strokeWidth={1.6} style={{ color: C.orange }} aria-hidden />
      </div>
      <div>
        <div style={{
          fontFamily: ff, fontSize: "0.68rem", fontWeight: 500,
          letterSpacing: isAr ? 0 : "0.18em", textTransform: isAr ? "none" : "uppercase",
          color: C.inkInverseDim, marginBottom: 8,
        }}>{label}</div>
        {href ? (
          <a href={href} target="_blank" rel="noopener noreferrer"
            dir={ltr ? "ltr" : undefined}
            className="mpl-contact-value"
            style={{
              fontFamily: ff, fontSize: "0.98rem", fontWeight: isAr ? 500 : 400,
              lineHeight: isAr ? 1.7 : 1.5,
              color: C.inkInverse, textDecoration: "none",
              unicodeBidi: ltr ? "embed" : undefined,
              transition: "color 200ms",
            }}>{value}</a>
        ) : (
          <span style={{
            fontFamily: ff, fontSize: "0.98rem", fontWeight: isAr ? 500 : 400,
            lineHeight: isAr ? 1.7 : 1.5, color: C.inkInverse,
          }}>{value}</span>
        )}
      </div>
    </div>
  );

  // Secondary action link (map / linkedin) — ghost pill
  const actionLink = (Icon, label, href) => (
    <a href={href} target="_blank" rel="noopener noreferrer"
      className="mpl-link-btn"
      style={{
        fontFamily: ff, fontSize: "0.84rem", fontWeight: isAr ? 500 : 450,
        letterSpacing: isAr ? 0 : "0.03em",
        color: C.inkInverse, textDecoration: "none",
        border: `1px solid ${C.hairlineInverse}`, borderRadius: 3,
        padding: "13px 22px",
        display: "inline-flex", alignItems: "center", gap: 10,
        transition: "border-color 220ms, background-color 220ms",
      }}>
      <Icon size={16} strokeWidth={1.6} style={{ color: C.orange }} aria-hidden />
      {label}
    </a>
  );

  return (
    <section style={{ background: C.dark }} id="contact">
      <div style={{ ...wrap, paddingBlock: "clamp(88px, 12vw, 160px)" }}>

        {/* ── Opener: centered hierarchy ── */}
        <div style={{ textAlign: "center", maxWidth: "44ch", marginInline: "auto" }}>
          <FadeUp>
            <div style={{ display: "inline-flex", alignItems: "center", gap: 12, marginBottom: 28 }}>
              <span aria-hidden style={{ width: 28, height: 1, background: C.orange }} />
              <span style={{
                fontFamily: ff, fontSize: "0.72rem", fontWeight: 500,
                letterSpacing: isAr ? 0 : "0.22em", textTransform: isAr ? "none" : "uppercase",
                color: C.orange,
              }}>{t.eyebrow}</span>
              <span aria-hidden style={{ width: 28, height: 1, background: C.orange }} />
            </div>
          </FadeUp>
          <FadeUp delay={80}>
            <h2 style={{
              ...fontDisplay(lang),
              fontSize: "clamp(2.4rem, 5vw, 4rem)",
              color: C.inkInverse, lineHeight: isAr ? 1.25 : 1.05,
            }}>{t.headline}</h2>
          </FadeUp>
          <FadeUp delay={140}>
            <p style={{
              fontFamily: ff, fontSize: "1.02rem", fontWeight: 400,
              lineHeight: isAr ? 1.9 : 1.6, color: C.inkInverseDim,
              marginTop: 22,
            }}>{t.sub}</p>
          </FadeUp>
        </div>

        {/* ── Primary CTA ── */}
        <FadeUp delay={180}>
          <div style={{ display: "flex", justifyContent: "center", marginTop: "clamp(40px, 5vw, 60px)" }}>
            <button type="button" onClick={() => onInquire()}
              className="mpl-solid-btn"
              style={{
                display: "inline-flex", alignItems: "center", gap: 14,
                fontFamily: ff, fontSize: "1rem", fontWeight: 600,
                letterSpacing: isAr ? 0 : "0.02em",
                color: C.dark, background: C.orange, border: `1px solid ${C.orange}`,
                borderRadius: 3, padding: "18px 36px", cursor: "pointer",
              }}>
              {t.cta.title}
              {isAr
                ? <ArrowLeft className="mpl-arrow" size={19} strokeWidth={2} aria-hidden />
                : <ArrowRight className="mpl-arrow" size={19} strokeWidth={2} aria-hidden />}
            </button>
          </div>
        </FadeUp>

        {/* ── Divider ── */}
        <div style={{
          height: 1, background: C.hairlineInverse,
          maxWidth: 720, marginInline: "auto",
          marginTop: "clamp(56px, 7vw, 88px)", marginBottom: "clamp(48px, 6vw, 72px)",
        }} aria-hidden />

        {/* ── Contact details: clean three-up row ── */}
        <FadeUp delay={120}>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-x-12 gap-y-10" style={{ maxWidth: 940, marginInline: "auto" }}>
            {detail(Phone, isAr ? "الهاتف" : "Phone", t.info.phone, `tel:${t.info.phone.replace(/\s/g, "")}`, true)}
            {detail(Mail, isAr ? "البريد الإلكتروني" : "Email", t.info.email, `mailto:${t.info.email}`, true)}
            {detail(MapPin, isAr ? "العنوان" : "Address", t.info.address, MAP_URL, false)}
          </div>
        </FadeUp>

        {/* ── Secondary actions ── */}
        <FadeUp delay={180}>
          <div className="flex flex-wrap items-center justify-center gap-3" style={{ marginTop: "clamp(44px, 5vw, 64px)" }}>
            {actionLink(MessageCircle, t.info.whatsappLabel, waLink(lang))}
            {actionLink(MapPin, t.info.mapLabel, MAP_URL)}
            {actionLink(Linkedin, t.info.linkedinLabel, LI_URL)}
            {/* ── Company Profile PDF download ── */}
            <a
              href={PDF_URL}
              target="_blank"
              rel="noopener noreferrer"
              download="MPL-Company-Profile.pdf"
              className="mpl-link-btn"
              style={{
                fontFamily: ff, fontSize:"0.84rem", fontWeight: isAr ? 500 : 450,
                letterSpacing: isAr ? 0 : "0.03em",
                color: C.inkInverse, textDecoration:"none",
                border:`1px solid ${C.hairlineInverse}`, borderRadius:3,
                padding:"13px 22px",
                display:"inline-flex", alignItems:"center", gap:10,
                transition:"border-color 220ms, background-color 220ms",
              }}
            >
              <FileCheck2 size={16} strokeWidth={1.6} style={{ color: C.orange }} aria-hidden />
              {t.info.pdfLabel}
            </a>
          </div>
        </FadeUp>

        {/* ── Logo mark ── */}
        <FadeUp delay={240}>
          <div style={{ display: "flex", justifyContent: "center", marginTop: "clamp(72px, 9vw, 120px)", opacity: 0.96 }}>
            <Logo height={160} />
          </div>
        </FadeUp>

      </div>
    </section>
  );
}

/* ── Slim footer */
function GlobalFooter({ lang }) {
  const t = T[lang].footer;
  const isAr = lang === "ar";
  const wrap = { maxWidth: 1280, marginInline: "auto", paddingInline: "clamp(20px, 5vw, 72px)" };

  return (
    <footer style={{ background: C.dark, borderTop: `1px solid ${C.hairlineInverse}` }}>
      <div style={wrap}
        className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <span style={{
          fontFamily: isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Inter', sans-serif",
          fontSize: "0.72rem", fontWeight: 400,
          color: C.inkInverseDim, letterSpacing: isAr ? 0 : "0.03em",
          paddingBlock: "clamp(20px, 3vw, 36px)",
        }}>{t.legal}</span>
        <span style={{
          fontFamily: isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Inter', sans-serif",
          fontSize: "0.72rem", color: C.inkTertiary,
          letterSpacing: isAr ? 0 : "0.06em",
        }}>{t.cities}</span>
      </div>
    </footer>
  );
}

/* ══════════════════════════════════════════════════════════════════
   MAIN APPLICATION
   State: lang (ar default) + page (home default)
   RTL-first: dir="rtl" on root, flips to "ltr" on EN toggle.
   CSS logical properties throughout guarantee structural parity.
══════════════════════════════════════════════════════════════════ */
/* ══════════════════════════════════════════════════════════════════
   INQUIRY MODAL — two-step qualifier form
   Privacy: data goes from the visitor's device straight into WhatsApp.
   No third-party service ever holds it.
   PRODUCTION HOOK: to deliver to your OWN backend instead (no middleman),
   POST `payload` to your API route at the marked line in handleSubmit().
══════════════════════════════════════════════════════════════════ */
function ARorIN(isAr) { return isAr ? "'IBM Plex Sans Arabic', sans-serif" : "'Inter', sans-serif"; }

function InquiryModal({ open, onClose, lang, preset }) {
  const L = T[lang].form;
  const isAr = lang === "ar";
  const ff = ARorIN(isAr);

  const [shown, setShown] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [waUrl, setWaUrl] = useState("");

  const [name, setName] = useState("");
  const [company, setCompany] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [services, setServices] = useState([]);
  const [location, setLocation] = useState(null);
  const [message, setMessage] = useState("");
  const [errors, setErrors] = useState({});

  const panelRef = useRef(null);
  const scrimRef = useRef(null);

  const requestClose = useCallback(() => {
    if (prefersReducedMotion()) { onClose(); return; }
    setShown(false);
    setTimeout(onClose, 200);
  }, [onClose]);

  /* Reset + entrance animation when opened */
  useEffect(() => {
    if (!open) { setShown(false); return; }
    setSubmitted(false); setErrors({}); setWaUrl("");
    setName(""); setCompany(""); setPhone(""); setEmail("");
    setServices([]); setLocation(null); setMessage("");
    const raf = requestAnimationFrame(() => setShown(true));
    return () => cancelAnimationFrame(raf);
  }, [open]);

  /* Body scroll lock + Esc + focus trap */
  useEffect(() => {
    if (!open) return;
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const onKey = (e) => {
      if (e.key === "Escape") { e.preventDefault(); requestClose(); return; }
      if (e.key === "Tab" && panelRef.current) {
        const f = panelRef.current.querySelectorAll(
          'button:not([disabled]),input,textarea,select,a[href],[tabindex]:not([tabindex="-1"])'
        );
        if (!f.length) return;
        const first = f[0], last = f[f.length - 1];
        if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
      }
    };
    document.addEventListener("keydown", onKey);
    const t = setTimeout(() => {
      const el = panelRef.current && panelRef.current.querySelector("input,textarea,button");
      if (el) el.focus();
    }, 70);
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = prevOverflow;
      clearTimeout(t);
    };
  }, [open, requestClose]);

  if (!open) return null;
  const reduce = prefersReducedMotion();

  const toggleService = (i) =>
    setServices((s) => (s.includes(i) ? s.filter((x) => x !== i) : [...s, i]));

  const handleSubmit = () => {
    const e = {};
    if (!name.trim()) e.name = L.errName;
    if (!phone.trim() && !email.trim()) e.contact = L.errContact;
    setErrors(e);
    if (Object.keys(e).length) return;

    const serviceLabels = services.map((i) => L.serviceItems[i]).join(L.sep);
    const lines = [
      L.waHeader, "",
      L.waName + ": " + name,
      company.trim() ? (L.waCompany + ": " + company) : null,
      phone.trim() ? (L.waPhone + ": " + phone) : null,
      email.trim() ? (L.waEmail + ": " + email) : null,
      services.length ? (L.waServices + ": " + serviceLabels) : null,
      location != null ? (L.waLocation + ": " + L.locationItems[location]) : null,
      message.trim() ? (L.waMessage + ": " + message) : null,
    ].filter(Boolean);
    const text = lines.join("\n");

    /* ── PRODUCTION HOOK ────────────────────────────────────────────
       To deliver to your OWN backend (no third party holds the data):
         const payload = { name, company, phone, email,
           services: services.map(i => L.serviceItems[i]),
           location: location != null ? L.locationItems[location] : null,
           message, lang };
         await fetch("/api/inquiry", { method:"POST",
           headers:{ "Content-Type":"application/json" },
           body: JSON.stringify(payload) });
       Until that exists, we route via the visitor's own WhatsApp — no middleman.
    ──────────────────────────────────────────────────────────────── */
    const url = "https://wa.me/" + WA_NUMBER + "?text=" + encodeURIComponent(text);
    setWaUrl(url);
    setSubmitted(true);
    window.open(url, "_blank", "noopener,noreferrer");
  };

  const inputStyle = {
    width: "100%", fontFamily: ff, fontSize: "0.95rem",
    color: C.inkPrimary, background: C.white,
    border: "1px solid " + C.hairlineStrong, borderRadius: 2,
    padding: "14px 14px", outline: "none", boxSizing: "border-box",
  };
  const labelStyle = {
    display: "block", fontFamily: ff, fontSize: "0.74rem", fontWeight: 500,
    color: C.inkSecondary, marginBottom: 7, letterSpacing: isAr ? 0 : "0.04em",
  };
  const errStyle = { fontFamily: ff, fontSize: "0.72rem", color: "#B0392B", marginTop: 6 };

  const field = (label, required, error, children) => (
    <div style={{ marginBottom: 16 }}>
      <label style={labelStyle}>{label}{required && <span style={{ color: C.orange }}> *</span>}</label>
      {children}
      {error && <div style={errStyle}>{error}</div>}
    </div>
  );

  return (
    <div
      ref={scrimRef}
      role="dialog" aria-modal="true" aria-label={L.title}
      onMouseDown={(e) => { if (e.target === scrimRef.current) requestClose(); }}
      style={{
        position: "fixed", inset: 0, zIndex: 200,
        background: "rgba(42,40,38,0.55)",
        display: "flex", alignItems: "center", justifyContent: "center",
        padding: "clamp(14px, 4vw, 40px)",
        opacity: shown ? 1 : 0,
        transition: reduce ? "none" : "opacity 220ms ease",
        WebkitBackdropFilter: "blur(2px)", backdropFilter: "blur(2px)",
      }}
    >
      <div
        ref={panelRef}
        style={{
          width: "100%", maxWidth: 560, maxHeight: "90vh", overflowY: "auto",
          background: C.canvas, borderRadius: 4,
          transform: shown ? "translateY(0) scale(1)" : "translateY(14px) scale(0.985)",
          transition: reduce ? "none" : "transform 280ms cubic-bezier(0.16,1,0.3,1)",
          boxSizing: "border-box",
        }}
      >
        {/* Header */}
        <div style={{
          display: "flex", alignItems: "flex-start", justifyContent: "space-between",
          padding: "clamp(24px,4vw,36px) clamp(24px,4vw,36px) 0",
        }}>
          <div>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <span aria-hidden style={{ width: 24, height: 1, background: C.orange }} />
              <span style={{
                fontFamily: ff, fontSize: "0.7rem", fontWeight: 500,
                letterSpacing: isAr ? 0 : "0.2em", textTransform: isAr ? "none" : "uppercase",
                color: C.inkTertiary,
              }}>{L.title}</span>
            </div>
            {!submitted && (
              <p style={{ ...fontBody(lang), fontSize: "0.95rem", color: C.inkSecondary, marginTop: 14, maxWidth: "44ch" }}>
                {L.subtitle}
              </p>
            )}
          </div>
          <button onClick={requestClose} aria-label={L.close} style={{
            background: "transparent", border: "none", cursor: "pointer",
            color: C.inkTertiary, padding: 6, marginInlineStart: 12, flexShrink: 0, lineHeight: 0,
          }}>
            <X size={22} strokeWidth={1.6} />
          </button>
        </div>

        {/* Body */}
        <div style={{ padding: "clamp(20px,3vw,26px) clamp(24px,4vw,36px) clamp(24px,4vw,36px)" }}>
          {submitted ? (
            <div style={{ textAlign: "center", paddingBlock: 12 }}>
              <div style={{
                width: 56, height: 56, borderRadius: "50%",
                background: "rgba(26,122,74,0.10)", border: "1px solid rgba(26,122,74,0.3)",
                display: "flex", alignItems: "center", justifyContent: "center",
                marginInline: "auto", marginBottom: 22,
              }}>
                <Check size={26} strokeWidth={2} style={{ color: C.success }} aria-hidden />
              </div>
              <h3 style={{ ...fontDisplay(lang), fontSize: "1.4rem", color: C.inkPrimary }}>{L.successTitle}</h3>
              <p style={{ ...fontBody(lang), fontSize: "0.95rem", color: C.inkSecondary, marginTop: 12, maxWidth: "40ch", marginInline: "auto" }}>
                {L.successBody}
              </p>
              <a href={waUrl} target="_blank" rel="noopener noreferrer" className="mpl-solid-btn"
                style={{
                  display: "inline-flex", alignItems: "center", gap: 9, marginTop: 26,
                  fontFamily: ff, fontSize: "0.88rem", fontWeight: isAr ? 600 : 500,
                  color: C.dark, background: C.orange, border: "1px solid " + C.orange,
                  borderRadius: 2, padding: "13px 24px", textDecoration: "none", cursor: "pointer",
                }}>
                <MessageCircle size={17} strokeWidth={2} aria-hidden />
                {L.successCta}
              </a>
            </div>
          ) : (
            <>
              {field(L.name, true, errors.name,
                <input className="mpl-input" style={inputStyle} value={name}
                  onChange={(e) => setName(e.target.value)} />
              )}
              {field(L.company, false, null,
                <input className="mpl-input" style={inputStyle} value={company}
                  onChange={(e) => setCompany(e.target.value)} />
              )}
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(min(100%, 220px), 1fr))", gap: 12 }}>
                {field(L.phone, false, errors.contact,
                  <input className="mpl-input" dir="ltr" style={{ ...inputStyle, textAlign: isAr ? "right" : "left" }}
                    value={phone} onChange={(e) => setPhone(e.target.value)} inputMode="tel" />
                )}
                {field(L.email, false, null,
                  <input className="mpl-input" dir="ltr" style={{ ...inputStyle, textAlign: isAr ? "right" : "left" }}
                    value={email} onChange={(e) => setEmail(e.target.value)} inputMode="email" />
                )}
              </div>
              {field(L.services, false, null,
                <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                  {L.serviceItems.map((s, i) => {
                    const on = services.includes(i);
                    return (
                      <button key={i} onClick={() => toggleService(i)} style={{
                        fontFamily: ff, fontSize: "0.8rem", fontWeight: on ? 500 : 400,
                        padding: "9px 14px", borderRadius: 2, cursor: "pointer",
                        border: "1px solid " + (on ? C.orange : C.hairlineStrong),
                        background: on ? C.orangeTint : "transparent",
                        color: on ? C.inkPrimary : C.inkSecondary, transition: "all 200ms",
                      }}>{s}</button>
                    );
                  })}
                </div>
              )}
              {field(L.location, false, null,
                <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                  {L.locationItems.map((s, i) => {
                    const on = location === i;
                    return (
                      <button key={i} onClick={() => setLocation(on ? null : i)} style={{
                        fontFamily: ff, fontSize: "0.8rem", fontWeight: on ? 500 : 400,
                        padding: "9px 14px", borderRadius: 2, cursor: "pointer",
                        border: "1px solid " + (on ? C.orange : C.hairlineStrong),
                        background: on ? C.orangeTint : "transparent",
                        color: on ? C.inkPrimary : C.inkSecondary, transition: "all 200ms",
                      }}>{s}</button>
                    );
                  })}
                </div>
              )}
              {field(L.message, false, null,
                <textarea className="mpl-input" rows={3} style={{ ...inputStyle, resize: "vertical", minHeight: 84 }}
                  placeholder={L.messagePlaceholder}
                  value={message} onChange={(e) => setMessage(e.target.value)} />
              )}
            </>
          )}
        </div>

        {/* Footer */}
        {!submitted && (
          <div style={{
            display: "flex", justifyContent: "flex-end",
            padding: "0 clamp(24px,4vw,36px) clamp(24px,4vw,36px)",
          }}>
            <button onClick={handleSubmit} className="mpl-solid-btn" style={{
              display: "inline-flex", alignItems: "center", gap: 8,
              fontFamily: ff, fontSize: "0.86rem", fontWeight: 600,
              color: C.dark, background: C.orange, border: "1px solid " + C.orange,
              borderRadius: 2, padding: "13px 28px", cursor: "pointer",
            }}>
              <MessageCircle size={16} strokeWidth={2} aria-hidden />
              {L.submit}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

function MPLApp() {
  const [lang, setLang] = useState("ar");   // Arabic default — non-negotiable
  const [fading, setFading] = useState(false);
  const [inquiryOpen, setInquiryOpen] = useState(false);
  const [inquiryPreset, setInquiryPreset] = useState("enterprise");
  const [activeSection, setActiveSection] = useState("home");
  const sectionRefs = useRef({});
  const navRef = useRef(null);
  const isAr = lang === "ar";

  /* Measure real nav height so scrollMarginTop is always exact */
  const [navHeight, setNavHeight] = useState(72);
  useEffect(() => {
    const el = navRef.current;
    if (!el) return;
    const ro = new ResizeObserver(([entry]) => {
      setNavHeight(Math.ceil(entry.contentRect.height));
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const openInquiry = useCallback((preset = "enterprise") => {
    setInquiryPreset(preset);
    setInquiryOpen(true);
  }, []);

  /* Smooth-scroll to a section by id (one-page navigation) */
  const scrollToSection = useCallback((id) => {
    const el = sectionRefs.current[id];
    if (!el) return;
    const reduce = prefersReducedMotion();
    el.scrollIntoView({ behavior: reduce ? "auto" : "smooth", block: "start" });
  }, []);

  /* Language switch with crossfade — content fades out, swaps, fades in.
     Reduced motion: instant swap, no fade. */
  const switchLang = useCallback(() => {
    if (prefersReducedMotion()) {
      setLang((l) => (l === "ar" ? "en" : "ar"));
      return;
    }
    setFading(true);
    setTimeout(() => {
      setLang((l) => (l === "ar" ? "en" : "ar"));
      setFading(false);
    }, 200);
  }, []);

  /* Load fonts — IBM Plex Sans Arabic + Space Grotesk + Inter */
  useEffect(() => {
    const id = "mpl-gfonts";
    if (document.getElementById(id)) return;
    const lnk = document.createElement("link");
    lnk.id = id; lnk.rel = "stylesheet";
    lnk.href =
      "https://fonts.googleapis.com/css2?" +
      "family=IBM+Plex+Sans+Arabic:wght@300;400;500;600;700" +
      "&family=Space+Grotesk:wght@400;500;600;700" +
      "&family=Inter:wght@300;400;500;600&display=swap";
    document.head.appendChild(lnk);
  }, []);

  /* Scroll-spy — highlight the section currently in view.
     IntersectionObserver = no scroll-jank. */
  useEffect(() => {
    const ids = ["home", "expertise", "work", "company", "contact"];
    const io = new IntersectionObserver(
      (entries) => {
        // Pick the most-visible intersecting section
        let best = null, bestRatio = 0;
        entries.forEach((e) => {
          if (e.isIntersecting && e.intersectionRatio > bestRatio) {
            best = e.target.id; bestRatio = e.intersectionRatio;
          }
        });
        if (best) setActiveSection(best);
      },
      { rootMargin: "-45% 0px -45% 0px", threshold: [0, 0.25, 0.5, 0.75, 1] }
    );
    ids.forEach((id) => {
      const el = sectionRefs.current[id];
      if (el) io.observe(el);
    });
    return () => io.disconnect();
  }, []);

  return (
    <div
      dir={isAr ? "rtl" : "ltr"}
      lang={lang}
      style={{ background: C.canvas, color: C.inkPrimary, minHeight: "100vh" }}
    >
      {/* ── Global styles: hover, motion, selection, marquee, responsive */}
      <style>{`
        html { scroll-behavior: smooth; }
        @media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }
        * { -webkit-tap-highlight-color: transparent; box-sizing: border-box; }
        html, body { max-width: 100%; overflow-x: hidden; }

        /* ════════════════════════════════════════════════════════════
           SELF-CONTAINED LAYOUT UTILITIES
           Mirrors the Tailwind classes the markup uses, so the layout
           is robust whether or not a Tailwind runtime is present.
           Mobile-first base, then sm(≥640) / md(≥768) / lg(≥1024).
        ════════════════════════════════════════════════════════════ */
        .flex { display: flex; }
        .grid { display: grid; }
        .flex-col { flex-direction: column; }
        .flex-wrap { flex-wrap: wrap; }
        .items-center { align-items: center; }
        .items-start { align-items: flex-start; }
        .items-end { align-items: flex-end; }
        .justify-between { justify-content: space-between; }
        .justify-center { justify-content: center; }
        .h-full { height: 100%; }
        .w-full { width: 100%; }
        .text-start { text-align: start; }
        .gap-2 { gap: 0.5rem; }
        .gap-3 { gap: 0.75rem; }
        .gap-4 { gap: 1rem; }
        .gap-5 { gap: 1.25rem; }
        .gap-6 { gap: 1.5rem; }
        .gap-8 { gap: 2rem; }
        .gap-x-10 { column-gap: 2.5rem; }
        .gap-x-12 { column-gap: 3rem; }
        .gap-x-8 { column-gap: 2rem; }
        .gap-y-6 { row-gap: 1.5rem; }
        .gap-y-8 { row-gap: 2rem; }
        .gap-y-10 { row-gap: 2.5rem; }
        .gap-y-14 { row-gap: 3.5rem; }
        .grid-cols-1 { grid-template-columns: repeat(1, minmax(0,1fr)); }

        /* ── Card grids: intrinsic auto-fit. These reflow by AVAILABLE
           WIDTH, not viewport breakpoints — so they can't break at any
           specific screen size. The md:/sm:/lg: classes below opt each
           grid into a sensible minimum card width. ── */
        .sm\\:grid-cols-2,
        .md\\:grid-cols-2 { grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr)); }
        .md\\:grid-cols-3,
        .lg\\:grid-cols-3 { grid-template-columns: repeat(auto-fit, minmax(min(100%, 190px), 1fr)); }
        .lg\\:grid-cols-4 { grid-template-columns: repeat(auto-fit, minmax(min(100%, 220px), 1fr)); }

        .sm\\:flex-row { flex-direction: row; }
        .sm\\:items-center { align-items: center; }
        .sm\\:justify-between { justify-content: space-between; }
        .md\\:flex-row { flex-direction: row; }
        .md\\:items-end { align-items: flex-end; }
        .md\\:justify-between { justify-content: space-between; }
        @media (min-width: 1024px) {
          .lg\\:flex-row { flex-direction: row; }
          .lg\\:items-end { align-items: flex-end; }
        }

        /* ── 12-column asymmetric layout grids: only split when there's
           genuine room (≥820px of container), else stack cleanly. ── */
        @media (min-width: 820px) {
          .md\\:grid-cols-12 { grid-template-columns: repeat(12, minmax(0,1fr)); }
          .md\\:col-span-5 { grid-column: span 5 / span 5; }
          .md\\:col-span-6 { grid-column: span 6 / span 6; }
          .md\\:col-span-7 { grid-column: span 7 / span 7; }
          .md\\:col-span-12 { grid-column: span 12 / span 12; }
        }

        /* ── Navigation: desktop links vs mobile hamburger ── */
        .mpl-nav-links { display: flex; align-items: center; gap: clamp(16px, 2.4vw, 30px); }
        .mpl-burger { display: none; }
        .mpl-mobile-menu { display: none; }
        @media (max-width: 860px) {
          .mpl-nav-links { display: none; }
          .mpl-lang-toggle { display: none; }
          .mpl-burger { display: inline-flex; }
          .mpl-mobile-menu { display: block; }
        }

        /* ── Hero background: responsive image positioning ── */
        .mpl-hero-section {
          background-size: cover;
          background-repeat: no-repeat;
          background-position: 62% 42%;
        }
        @media (max-width: 1024px) {
          .mpl-hero-section { background-position: 68% 38%; }
        }
        @media (max-width: 640px) {
          /* Image fills full screen — hero locked to viewport height */
          .mpl-hero-section {
            background-position: center center !important;
            height: 100svh;
            overflow: hidden;
          }

          /* Overlay: elegant gradient, not a black box —
             soft at top so the crane reads clearly, graduated
             to a subtle dark at bottom for CTA readability */
          .mpl-hero-overlay {
            background: linear-gradient(to bottom,
              rgba(10,8,6,0.18)  0%,
              rgba(10,8,6,0.22) 30%,
              rgba(10,8,6,0.38) 60%,
              rgba(10,8,6,0.52) 100%) !important;
          }

          /* Anchor content from the TOP at ~18% of viewport height so
             the block sits in the upper-middle third — no large empty
             gap above, framed intentionally against the image. */
          .mpl-hero-content {
            justify-content: flex-start !important;
            padding-top: clamp(84px, 11vh, 130px) !important;
            padding-bottom: clamp(28px, 5vh, 60px) !important;
          }
        }
        /* ── Cinematic overlay — single elegant gradient.
           Bottom darkens to anchor content; upper stays lighter
           so the image breathes and feels full-screen.             */
        .mpl-hero-overlay {
          position: absolute; inset: 0; pointer-events: none;
          background: linear-gradient(to bottom,
            rgba(10,8,6,0.00)  0%,
            rgba(10,8,6,0.08) 30%,
            rgba(10,8,6,0.28) 60%,
            rgba(10,8,6,0.48) 100%);
        }


        /* Form inputs */
        .mpl-input { transition: border-color 200ms ease; }
        .mpl-input:focus { border-color: rgba(248,167,64,0.65) !important; }
        .mpl-input::placeholder { color: ${C.inkTertiary}; opacity: 0.8; }
        /* Card hover */
        .mpl-card { transition: border-color 300ms ease, background-color 300ms ease, transform 300ms cubic-bezier(0.16,1,0.3,1); }
        .mpl-card:hover { border-color: ${C.hairlineOrange}; background-color: ${C.white}; transform: translateY(-3px); }
        /* Compliance badge hover */
        .mpl-cbadge { transition: border-color 300ms ease; }
        .mpl-cbadge:hover { border-color: rgba(26,122,74,0.55); }
        /* Ghost CTA */
        .mpl-ghost-btn { transition: border-color 300ms ease, background-color 300ms ease; }
        .mpl-ghost-btn:hover { border-color: rgba(248,167,64,0.55); background-color: rgba(248,167,64,0.06); }
        /* Solid CTA */
        .mpl-solid-btn { transition: background-color 300ms ease; }
        .mpl-solid-btn:hover { background-color: #f9b558; }
        /* Link buttons */
        .mpl-link-btn:hover { border-color: rgba(248,167,64,0.5) !important; }
        .mpl-contact-value:hover { color: ${C.orange} !important; }
        /* Hero CTA */
        .mpl-hero-cta:hover { background-color: #3d3b39; }
        /* Outline ghost */
        .mpl-cta-ghost:hover { border-color: ${C.hairlineOrange}; }
        /* Arrow nudge */
        .mpl-arrow { transition: transform 300ms cubic-bezier(0.16,1,0.3,1); }
        .mpl-ghost-btn:hover .mpl-arrow,
        .mpl-solid-btn:hover .mpl-arrow { transform: translateX(${isAr ? "-" : ""}5px); }
        /* Marquee — LTR */
        .mpl-marquee { animation: mpl-ltr 40s linear infinite; }
        @keyframes mpl-ltr { from { transform: translateX(0); } to { transform: translateX(-33.33%); } }
        /* Marquee — RTL */
        .mpl-marquee-rtl { animation: mpl-rtl 40s linear infinite; }
        @keyframes mpl-rtl { from { transform: translateX(0); } to { transform: translateX(33.33%); } }
        /* Text selection */
        ::selection { background: rgba(248,167,64,0.22); color: ${C.inkPrimary}; }
        /* Focus ring */
        a:focus-visible, button:focus-visible {
          outline: 2px solid ${C.orange}; outline-offset: 3px; border-radius: 2px;
        }
        /* ── Services grid: 2 columns on ALL mobile widths (01|02 / 03|04),
           4 columns on desktop. Never a full-width orphaned card 04. ── */
        .mpl-services-grid {
          display: grid;
          gap: 12px;
          grid-template-columns: repeat(2, 1fr);
        }
        /* Card internals tighten slightly at 2-col mobile for balance */
        .mpl-services-grid .mpl-card { padding: clamp(16px, 4vw, 34px) !important; }
        .mpl-services-grid .mpl-card h3 { font-size: clamp(1.05rem, 4.4vw, 1.55rem) !important; }
        @media (min-width: 560px) {
          .mpl-services-grid { gap: 16px; }
        }
        @media (min-width: 1024px) {
          .mpl-services-grid { grid-template-columns: repeat(4, 1fr); }
        }

        /* ── Disciplines grid (Services page): 2-col mobile (01|02 / 03|04),
           desktop = 3 across + MEP featured full-width row ── */
        .mpl-disc-grid {
          display: grid;
          gap: 12px;
          grid-template-columns: repeat(2, 1fr);
        }
        .mpl-disc-grid .mpl-card { padding: clamp(16px, 4vw, 38px); }
        /* MEP: on mobile show compact, hide featured */
        .mpl-mep-compact { display: flex; }
        .mpl-mep-featured { display: none; }
        @media (min-width: 560px) {
          .mpl-disc-grid { gap: 16px; }
        }
        @media (min-width: 1024px) {
          .mpl-disc-grid { grid-template-columns: repeat(3, 1fr); }
          /* MEP spans the full width as the featured card */
          .mpl-disc-grid > .mpl-disc-mep { grid-column: 1 / -1; }
          .mpl-disc-grid > .mpl-disc-mep .mpl-card { padding: clamp(28px, 3.4vw, 52px); }
          .mpl-mep-compact { display: none; }
          .mpl-mep-featured { display: flex; }
        }

        /* ── Contact action buttons: equal-width 2-col grid on mobile ── */
        .mpl-action-grid {
          display: grid;
          grid-template-columns: repeat(2, 1fr);
          gap: 12px;
          width: 100%;
          max-width: 560px;
          margin-inline: auto;
        }
        @media (min-width: 640px) {
          .mpl-action-grid {
            display: flex; flex-wrap: wrap;
            justify-content: center; max-width: none;
          }
        }
        .mpl-action-grid > a { justify-content: center; }

        @media (prefers-reduced-motion: reduce) {
          .mpl-card, .mpl-cbadge, .mpl-ghost-btn, .mpl-solid-btn,
          .mpl-hero-cta, .mpl-arrow, .mpl-marquee, .mpl-marquee-rtl {
            transition: none !important; animation: none !important;
          }
          .mpl-card:hover { transform: none !important; }
        }
      `}</style>

      <Nav lang={lang} setLang={switchLang} activeSection={activeSection} onNavTo={scrollToSection} navRef={navRef} />


      <div style={{
        opacity: fading ? 0 : 1,
        transition: prefersReducedMotion() ? "none" : "opacity 200ms ease",
      }}>
        <main>
          {/* HOME */}
          <section id="home" ref={(el) => (sectionRefs.current.home = el)}>
            <HeroSection       lang={lang} onNavigate={scrollToSection} onInquire={openInquiry} />
            <ClientMarquee     lang={lang} />
            <ComplianceSection lang={lang} />
          </section>


          {/* EXPERTISE */}
          <section id="expertise" ref={(el) => (sectionRefs.current.expertise = el)} style={{ scrollMarginTop: navHeight }}>
            <ExpertisePage lang={lang} />
          </section>


          {/* WORK */}
          <section id="work" ref={(el) => (sectionRefs.current.work = el)} style={{ scrollMarginTop: navHeight }}>
            <WorkPage lang={lang} />
          </section>


          {/* COMPANY */}
          <section id="company" ref={(el) => (sectionRefs.current.company = el)} style={{ scrollMarginTop: navHeight }}>
            <CompanyPage lang={lang} />
          </section>

        </main>

        {/* Contact + footer — page endpoint */}
        <section id="contact" ref={(el) => (sectionRefs.current.contact = el)} style={{ scrollMarginTop: navHeight }}>
          <ContactSection lang={lang} onInquire={openInquiry} />
        </section>
        <GlobalFooter   lang={lang} />
      </div>

      <InquiryModal
        open={inquiryOpen}
        onClose={() => setInquiryOpen(false)}
        lang={lang}
        preset={inquiryPreset}
      />
    </div>
  );
}


/* ── Mount ── */
const _root = ReactDOM.createRoot(document.getElementById("root"));
_root.render(React.createElement(MPLApp));
